INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(14730606, 'Ivy Shackles', '常春藤束缚', 'アイヴィ・シャックル', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，对方场上表侧表示存在的全部怪兽只在自己回合变成植物族。场上表侧表示存在的这张卡被对方的效果破坏送去墓地时，从自己卡组抽1张卡。'),
(30069399, 'Ivy Token', '常春藤壁', 'アイヴィ・ウォール', 'Token', 'Plant', NULL, NULL, NULL, NULL, NULL),
(3137279, 'Ixeep, Omen of the Ghoti', '游魊之兆 伊克西普', 'ゴーティスの兆イグジープ', 'Effect Monster', 'Fish', 'WATER', 4, 1500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：鱼族怪兽被除外的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡被除外的下个回合的准备阶段，以自己的墓地·除外状态的1张「魊影」陷阱卡为对象才能发动。那张卡在自己场上盖放。'),
(6544078, 'Izanagi', '伊奘凪', '伊弉凪', 'Effect Monster', 'Fairy', 'WIND', 6, 2200, 1000, '这张卡可以把手卡1只灵魂怪兽从游戏中除外从手卡特殊召唤。只要这张卡在自己场上表侧表示存在，自己场上存在的灵魂怪兽在结束阶段时回到手卡效果可以不发动。'),
(43543777, 'Izanami', '伊奘波', '伊弉波', 'Spirit Monster', 'Fairy', 'WATER', 4, 1100, 1800, '这张卡不能特殊召唤。召唤·反转的回合的结束阶段时回到持有者手卡。这张卡召唤·反转时，可以丢弃1张手卡把自己墓地存在的1只灵魂怪兽加入手卡。'),
(36539330, 'Jabbing Panda', '流水刺拳大熊猫', 'ジャブィアント・パンダ', 'Effect Monster', 'Beast-Warrior', 'WATER', 3, 1500, 1000, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：场上有兽战士族怪兽2只以上存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡从场上送去墓地的场合，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力上升500。'),
(23850421, 'Jack Wyvern', '劫持翼龙', 'ジャック・ワイバーン', 'Effect Monster', 'Machine', 'DARK', 4, 1800, NULL, '这个卡名的效果1回合只能使用1次。 ①：把自己场上1只机械族怪兽和这张卡除外，以自己墓地1只暗属性怪兽为对象才能发动。那只怪兽特殊召唤。'),
(51697825, 'Jack-In-The-Hand', '吓人的手中杰克', 'ジャック・イン・ザ・ハンド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把3只卡名不同的1星怪兽给对方观看，对方从那之中选1只加入自身手卡。自己从剩下的卡之中选1只加入手卡，剩余回到卡组。'),
(36016907, 'Jack-o-Bolan', '杰克麦瓜', 'ジャック・ア・ボーラン', 'Effect Monster', 'Zombie', 'FIRE', 7, 1500, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡丢弃1只不死族怪兽才能发动。这张卡从手卡特殊召唤。 ②：对方主要阶段，以自己或者对方的墓地1只不死族怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。那之后，表侧表示的这张卡直到结束阶段除外。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(90876561, 'Jack''s Knight', '卫兵骑士', 'ジャックス・ナイト', 'Normal Monster', 'Warrior', 'LIGHT', 5, 1900, 1000, '精通一切剑术的战士。正义感非常强烈，为守护弱者而战。'),
(81171949, 'Jackpot 7', '头奖壶7', 'ジャックポット７', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡回到卡组洗切。此外，这张卡被对方的卡的效果送去墓地时，这张卡从游戏中除外。这个效果从游戏中除外的自己的「头奖壶7」3张齐集时，自己决斗胜利。'),
(101303082, 'Jade Dragon Mech', NULL, NULL, 'Synchro Monster', 'Machine', 'WIND', 9, 2700, 1800, NULL),
(95214051, 'Jade Insect Whistle', '翡翠虫笛', '翡翠の蟲笛', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '对方从卡组中选择1张昆虫族怪兽卡，那张卡放在卡组最上面。'),
(44364207, 'Jade Knight', '翡翠骑士', 'ジェイドナイト', 'Effect Monster', 'Machine', 'LIGHT', 4, 1000, 1800, '只要这张卡在自己场上表侧攻击表示存在，自己场上表侧表示存在的攻击力1200以下的机械族怪兽不会被陷阱卡的效果破坏。场上表侧表示存在的这张卡被战斗破坏送去墓地时，可以从自己卡组把1只光属性·机械族的4星怪兽加入手卡。'),
(96235275, 'Jain, Lightsworn Paladin', '光道圣骑士 简', 'ライトロード・パラディン ジェイン', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1800, 1200, '①：这张卡向对方怪兽攻击的伤害步骤内，这张卡的攻击力上升300。 ②：自己结束阶段发动。从自己卡组上面把2张卡送去墓地。'),
(84673417, 'Jain, Twilightsworn General', '暮光道将军 简', 'トワイライトロード・ジェネラル ジェイン', 'Effect Monster', 'Warrior', 'DARK', 4, 1800, 1200, '①：1回合1次，从自己的手卡·墓地把1只「光道」怪兽除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力直到回合结束时下降除外的怪兽的等级×300。 ②：1回合1次，这张卡以外的自己的「光道」怪兽的效果发动的场合发动。从自己卡组上面把2张卡送去墓地。'),
(21770260, 'Jam Breeding Machine', '史莱姆增殖炉', 'スライム増殖炉', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次自己的准备阶段，在自己场上把1只「史莱姆怪兽衍生物」（水族·水·1星·攻/守500）攻击表示特殊召唤。只要这张卡在场上存在，自己不能把「史莱姆怪兽衍生物」以外的怪兽召唤·反转召唤·特殊召唤。'),
(21558682, 'Jam Defender', '防御史莱姆', 'ディフェンド・スライム', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方的怪兽对自己的怪兽攻击的时候，自己的场上的「再生史莱姆」表侧表示存在的场合，攻击对象移去「再生史莱姆」。'),
(98954106, 'Jar of Avarice', '贪欲之瓶', '貪欲な瓶', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「贪欲之瓶」在1回合只能发动1张。 ①：以「贪欲之瓶」以外的自己墓地5张卡为对象才能发动。那5张卡加入卡组洗切。那之后，自己从卡组抽1张。'),
(22454453, 'Jar of Generosity', '谦虚之瓶', '謙虚な瓶', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己选1张手卡回到卡组最上面或者最下面。'),
(83968380, 'Jar of Greed', '强欲之瓶', '強欲な瓶', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己从卡组抽1张。'),
(33784505, 'Jar Robber', '盗壶者', '壺盗み', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「强欲之壶」发动时才能发动。使「强欲之壶」的效果无效，从自己卡组抽1张卡。'),
(96287685, 'Jar Turtle', '瓶龟', '瓶亀', 'Effect Monster', 'Reptile', 'WATER', 4, 200, 2100, '只要这张卡在场上表侧表示存在，每次「强欲之瓶」发动从自己卡组抽1张卡。'),
(26932788, 'Javelin Beetle', '标枪甲虫', 'ジャベリンビートル', 'Ritual Monster', 'Insect', 'EARTH', 8, 2450, 2550, '借由「标枪甲虫的契约」降临。必须从场上或者手札，牺牲奉献等级合计为8个以上的卡。'),
(41182875, 'Javelin Beetle Pact', '标枪甲虫的契约', 'ジャベリンビートルの契約', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「标枪甲虫」的降临必要。必须从场上或者手札，牺牲奉献等级合计为8个以上的卡。'),
(50532786, 'Jawsman', '鲛颚人', 'ジョーズマン', 'Effect Monster', 'Beast-Warrior', 'WATER', 6, 2600, 1600, '这张卡不能特殊召唤。这张卡上级召唤的场合，解放的怪兽必须是水属性怪兽。这张卡的攻击力上升这张卡以外的自己场上表侧表示存在的水属性怪兽每1只300。'),
(41440817, 'Jelly Cannon', '心太炮式', '心太砲式', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己或者对方的怪兽的攻击宣言时，以场上1只怪兽为对象才能发动。那只怪兽回到持有者卡组。'),
(14851496, 'Jellyfish', '水母', '海月－ジェリーフィッシュ－', 'Normal Monster', 'Aqua', 'WATER', 4, 1200, 1500, '漂浮在海面上的海蜇，半透明的身体使人难以察觉。'),
(83725008, 'Jenis, Lightsworn Mender', '光道祭司 珍妮丝', 'ライトロード・プリースト ジェニス', 'Effect Monster', 'Spellcaster', 'LIGHT', 4, 300, 2100, '名字带有「光道」的卡的效果从自己卡组把卡送去墓地的回合的结束阶段时，给与对方基本分500分伤害，自己回复500基本分。'),
(23635815, 'Jerry Beans Man', '杰瑞豆人', 'ジェリービーンズマン', 'Normal Monster', 'Plant', 'EARTH', 3, 1750, NULL, '名叫软糖的豆战士。虽坚信自己就是世界最强的战士，其实力不得而知。'),
(8487449, 'Jester Confit', '滑稽艺人', 'ジェスター・コンフィ', 'Effect Monster', 'Spellcaster', 'DARK', 1, NULL, NULL, '①：「糖果小丑」在自己场上只能有1只表侧表示存在。 ②：这张卡可以从手卡攻击表示特殊召唤。 ③：这张卡的②的方法特殊召唤的场合，下次的对方结束阶段以对方场上1只表侧表示怪兽为对象发动。那只对方的表侧表示怪兽和表侧表示的这张卡回到持有者手卡。'),
(72992744, 'Jester Lord', '小丑王', 'ジェスター・ロード', 'Effect Monster', 'Spellcaster', 'DARK', 1, NULL, NULL, '场上没有这张卡以外的怪兽存在的场合，双方的魔法与陷阱卡区域存在的卡每有1张，这张卡的攻击力上升1000。'),
(9742784, 'Jet Synchron', '喷气同步士', 'ジェット・シンクロン', 'Tuner Monster', 'Machine', 'FIRE', 1, 500, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡作为同调素材送去墓地的场合才能发动。从卡组把1只「废品」怪兽加入手卡。 ②：这张卡在墓地存在的场合，把1张手卡送去墓地才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(286392, 'Jet Warrior', '喷气战士', 'ジェット・ウォリアー', 'Synchro Monster', 'Warrior', 'FIRE', 5, 2100, 1200, '「喷气同调士」＋调整以外的怪兽1只以上 「喷气战士」的①②的效果1回合各能使用1次。 ①：这张卡同调召唤成功的场合，以对方场上1张卡为对象才能发动。那张卡回到持有者手卡。 ②：这张卡在墓地存在的场合，把自己场上1只2星以下的怪兽解放才能发动。这张卡从墓地守备表示特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(43697559, 'Jetroid', '喷气机人', 'ジェット・ロイド', 'Effect Monster', 'Machine', 'WIND', 4, 1200, 1800, '这张卡被对方怪兽选作为攻击对象时，这张卡的控制者可以从手卡发动陷阱卡。'),
(72710085, 'Jewels of the Valiant', '星邪的神食', '星邪の神喰', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只让自己墓地的怪兽1只被从游戏中除外的场合，可以把和除外的那只怪兽不同属性的1只怪兽从卡组送去墓地。「星邪的神食」的效果1回合只能使用1次。'),
(25935625, 'Jiaotu, Darkness of the Yang Zing', '暗龙星－椒图', '闇竜星－ジョクト', 'Tuner Monster', 'Wyrm', 'DARK', 2, NULL, 2000, '「暗龙星-椒图」的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上的这张卡被战斗·效果破坏送去墓地时才能发动。从卡组把「暗龙星-椒图」以外的1只「龙星」怪兽攻击表示特殊召唤。 ②：自己场上没有这张卡以外的怪兽存在的场合，把手卡2张「龙星」卡送去墓地才能发动。从卡组把攻击力0和守备力0的「龙星」怪兽各1只特殊召唤。这个效果特殊召唤的怪兽在结束阶段除外。'),
(40894584, 'Jigabyte', '基哥百特', 'ジゴバイト', 'Effect Monster', 'Reptile', 'WATER', 4, 1500, 200, '①：「电豪灵蜥」在自己场上只能有1张表侧表示存在。 ②：自己场上有魔法师族怪兽存在的场合，这张卡可以从手卡特殊召唤。 ③：这张卡被战斗·效果破坏送去墓地时才能发动。从卡组把「电豪灵蜥」以外的1只攻击力1500/守备力200的怪兽特殊召唤。'),
(90020065, 'Jigen Bakudan', '定时炸弹', 'タイム・ボマー', 'Flip Effect Monster', 'Pyro', 'FIRE', 2, 200, 1000, '反转：自己的准备阶段把这张卡作为祭品。全部自己的怪兽破坏，给与对方那个总攻击力一半数值的伤害。'),
(77585513, 'Jinzo', '人造人-念力震慑者', '人造人間－サイコ・ショッカー', 'Effect Monster', 'Machine', 'DARK', 6, 2400, 1500, '①：只要这张卡在怪兽区域存在，双方不能把场上的陷阱卡的效果发动，场上的陷阱卡的效果无效化。'),
(51916032, 'Jinzo - Jector', '人造人-念力插孔者', '人造人間－サイコ・ジャッカー', 'Effect Monster', 'Machine', 'DARK', 4, 800, 2000, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「人造人-念力震慑者」使用。 ②：把这张卡解放才能发动。从卡组把「人造人-念力插孔者」以外的1只「人造人」怪兽加入手卡。那之后，对方的魔法与陷阱区域有盖放的卡的场合，那些全部确认。可以把最多有那之中的陷阱卡数量的「人造人」怪兽从手卡特殊召唤。'),
(99666430, 'Jinzo - Layered', '人造人－念力层叠者', '人造人間－サイコ・レイヤー', 'XYZ Monster', 'Machine', 'DARK', 6, 2400, 1500, '6星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。这个效果得到控制权的怪兽不能把效果发动，不能攻击宣言。 ②：场上有陷阱卡存在的场合才能发动。自己场上1只怪兽解放，选场上1张表侧表示的卡破坏。'),
(35803249, 'Jinzo - Lord', '人造人-念力王者', '人造人間－サイコ・ロード', 'Effect Monster', 'Machine', 'DARK', 8, 2600, 1600, '这张卡不能通常召唤。把自己场上1只表侧表示的「人造人-念力震慑者」送去墓地的场合才能特殊召唤。 ①：只要这张卡在怪兽区域存在，双方不能把场上的陷阱卡的效果发动，场上的陷阱卡的效果无效化。 ②：1回合1次，自己主要阶段才能发动。场上的表侧表示的陷阱卡全部破坏，给与对方破坏数量×300伤害。'),
(9418534, 'Jinzo - Returner', '人造人-念力归来者', '人造人間－サイコ・リターナー', 'Effect Monster', 'Machine', 'DARK', 3, 600, 1400, '①：这张卡可以直接攻击。 ②：这张卡被送去墓地时，以自己墓地1只「人造人-念力震慑者」为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在自己结束阶段破坏。'),
(32809211, 'Jinzo #7', '人造人7号', '人造人間７号', 'Effect Monster', 'Machine', 'DARK', 2, 500, 400, '这张卡可以直接攻击对方玩家。'),
(39987731, 'Jinzo the Machine Menace', '威胁的人造人-念力震慑者', '脅威の人造人間－サイコ・ショッカー', 'Effect Monster', 'Machine', 'DARK', 7, 2400, 1500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己或者对方的场上·墓地有陷阱卡存在的场合才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡的等级直到回合结束时变成6星。 ②：自己·对方的主要阶段，把这张卡解放才能发动。从自己的手卡·墓地选1只「人造人-念力震慑者」特殊召唤。那之后，可以把对方场上的陷阱卡全部破坏（那些卡在盖放中的场合，翻开确认）。'),
(92962242, 'Jioh the Gravity Ninja', '重之忍者-磁翁', '重の忍者－磁翁', 'Effect Monster', 'Rock', 'EARTH', 8, 2300, 2900, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤·反转的场合，以场上最多2只表侧表示怪兽为对象才能发动。那些怪兽变成里侧守备表示。这个效果变成里侧守备表示的对方场上的怪兽不能把表示形式变更。 ②：这张卡已在怪兽区域表侧表示存在的状态，场上的怪兽反转的场合，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(94773007, 'Jirai Gumo', '地雷蜘蛛', '地雷蜘蛛', 'Effect Monster', 'Insect', 'EARTH', 4, 2200, 100, '这张卡攻击宣言时，猜硬币的正反。猜中的话就继续攻击。猜不中的话自己的基本分减半再攻击。'),
(63941210, 'Jizukiru, the Star Destroying Kaiju', '坏星坏兽 机祖基鲁', '壊星壊獣ジズキエル', 'Effect Monster', 'Machine', 'LIGHT', 10, 3300, 2600, '①：这张卡可以把对方场上1只怪兽解放，从手卡往对方场上攻击表示特殊召唤。 ②：对方场上有「坏兽」怪兽存在的场合，这张卡可以从手卡攻击表示特殊召唤。 ③：「坏兽」怪兽在自己场上只能有1只表侧表示存在。 ④：只以卡1张为对象的魔法·陷阱·怪兽的效果发动时，把自己·对方场上3个坏兽指示物取除才能发动。那个效果无效。那之后，可以把场上1张卡破坏。'),
(14442329, 'JJ "Kewl Tune"', '地下俱乐部『杀手旋律』', 'ジュークジョイント“Killer Tune”', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：自己在通常召唤外加上只有1次，自己主要阶段可以把1只调整召唤。 ②：只要对方的场上或墓地有调整存在，自己场上的「杀手级调整曲响度战争」的攻击力上升3300。 ③：把自己场上1只调整解放才能发动。从卡组选1只「杀手级调整曲」怪兽加入手卡或特殊召唤。这个效果的发动后，直到回合结束时自己不是调整不能特殊召唤。'),
(55337339, 'Job-Change Mirror', '转职的魔镜', '転職の魔鏡', 'Normal Monster', 'Fiend', 'DARK', 3, 800, 1300, '恶魔镜。受到攻击也不会破裂、守备损伤。'),
(29284413, 'Joker''s Knight', '王牌骑士', 'ジョーカーズ・ナイト', 'Effect Monster', 'Warrior', 'LIGHT', 5, 2000, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把「王后骑士」「卫兵骑士」「国王骑士」之内1只送去墓地才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡直到结束阶段当作和送去墓地的怪兽同名卡使用。 ②：自己·对方的结束阶段，以这张卡以外的自己墓地1只战士族·光属性怪兽为对象才能发动。那只怪兽回到卡组，墓地的这张卡加入手卡。'),
(92067220, 'Joker''s Straight', '王牌顺子', 'ジョーカーズ・ストレート', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：选自己1张手卡丢弃，从卡组把1只「王后骑士」特殊召唤，从卡组把「国王骑士」「卫兵骑士」之内1只加入手卡。那之后，可以把1只怪兽召唤。这个回合，自己不是战士族·光属性怪兽不能从额外卡组特殊召唤。 ②：自己·对方的结束阶段，以自己墓地1只战士族·光属性怪兽为对象才能发动。那只怪兽回到卡组，墓地的这张卡加入手卡。'),
(81945678, 'Joker''s Wild', '王牌百搭', 'ジョーカーズ・ワイルド', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段以及战斗阶段，从卡组把有「王后骑士」「卫兵骑士」「国王骑士」的卡名全部记述的1张魔法卡送去墓地才能发动。这个效果变成和那张魔法卡发动时的效果相同。 ②：自己·对方的结束阶段，以自己墓地1只战士族·光属性怪兽为对象才能发动。那只怪兽回到卡组，墓地的这张卡加入手卡。'),
(8316565, 'Jolt Counter', '猛力反击', 'ジョルト・カウンター', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '自己场上有名字带有「燃烧拳击手」的怪兽存在的场合才能发动。战斗阶段中发动的效果怪兽的效果·魔法·陷阱卡的发动无效并破坏。'),
(47894537, 'Jongleur-Ghoul Illusionist', '团团转转幻术尸', 'ジョングルグールの幻術師', 'Normal Monster', 'Illusion', 'DARK', 4, 2000, NULL, '已很擅长活跃气氛的街头艺人　经常用歌舞引诱目标放松警惕　来势汹汹使出奇招怪术的攻击　不过其眼珠一转就是危险信号　及时察觉赶紧逃吧！'),
(2665273, 'Jormungandr, Generaider Boss of Eternity', '永之创王 奥姆加得', '永の王 オルムガンド', 'XYZ Monster', 'Reptile', 'EARTH', 9, -1, -1, '9星怪兽×2只以上 这个卡名的③的效果1回合只能使用1次。 ①：「永界王战 欧姆刚德王」在自己场上只能有1只表侧表示存在。 ②：这张卡的原本的攻击力·守备力变成这张卡的超量素材数量×1000。 ③：把这张卡1个超量素材取除才能发动。双方各自从卡组抽1张。那之后，抽卡的玩家选自身的手卡·场上1张卡在这张卡下面重叠作为超量素材。这个效果在对方回合也能发动。'),
(64203620, 'Jormungardr the Nordic Serpent', '极星邪龙 尤蒙刚德', '極星邪龍ヨルムンガンド', 'Effect Monster', 'Dragon', 'DARK', 8, 3000, 3000, '这张卡不能通常召唤。场上有「极神」怪兽存在的场合可以从手卡往对方场上守备表示特殊召唤。 ①：场上没有「极神」怪兽存在的场合这张卡破坏。 ②：只在这张卡在场上表侧表示存在才有1次，表侧守备表示的这张卡变成表侧攻击表示的场合发动。自己受到3000伤害。'),
(43685562, 'Joruri-P.U.N.K. Dangerous Gabu', '净－朋.克.危险裂口', 'Jo－P.U.N.K.デンジャラス・ガブ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。自己场上有「朋克」怪兽存在的场合，再让自己基本分回复作为对象的怪兽的原本攻击力的数值。'),
(82041999, 'Joruri-P.U.N.K. Madame Spider', '净－朋.克.蜘蛛夫人', 'Jo－P.U.N.K.Mme.スパイダー', 'Tuner Monster', 'Psychic', 'EARTH', 3, 900, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：支付600基本分才能发动。从卡组把1张「朋克」陷阱卡加入手卡。 ②：对方场上的卡为对象的「朋克」卡的效果由自己发动时，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成一半。'),
(70070211, 'Joruri-P.U.N.K. Nashiwari Surprise', '净－朋.克.梨割惊喜', 'Jo－P.U.N.K.ナシワリ・サプライズ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以对方场上盖放的1张卡为对象才能发动。那张卡破坏。自己场上有「朋克」怪兽存在的场合，也能作为代替以对方场上1张表侧表示的卡为对象。'),
(41855169, 'Jowgen the Spiritualist', '升灵术师 奘玄', '昇霊術師 ジョウゲン', 'Effect Monster', 'Spellcaster', 'LIGHT', 3, 200, 1300, '把手卡随机1张丢弃去墓地才能发动。场上的特殊召唤的怪兽全部破坏。此外，只要这张卡在场上表侧表示存在，双方不能把怪兽特殊召唤。'),
(5257687, 'Jowls of Dark Demise', '外界异物', 'X・E・N・O', 'Flip Effect Monster', 'Fiend', 'WATER', 2, 200, 100, '反转：在回合结束前得到对方场上1只怪兽的控制权。得到控制权的那只怪兽攻击的场合，可以直接攻击对方玩家。'),
(53054164, 'Joyous Melffys', '乐融融的梅尔菲们', 'わくわくメルフィーズ', 'XYZ Monster', 'Beast', 'EARTH', 2, 2000, 500, '兽族2星怪兽×2只以上 这个卡名的②的效果1回合只能使用1次。 ①：把这张卡1个超量素材取除才能发动。这个回合，自己的「童话动物」怪兽可以直接攻击。 ②：对方回合，以自己场上1只兽族超量怪兽为对象才能发动。那只怪兽回到额外卡组。那之后，可以把最多有那只怪兽持有的超量素材数量的2星以下的兽族怪兽从自己墓地特殊召唤。'),
(30113682, 'Judge Man', '审判者', 'ジャッジ・マン', 'Normal Monster', 'Warrior', 'EARTH', 6, 2200, 1500, '是个不喜欢比赛不分胜负的战士。棍棒的攻击很强！'),
(53535814, 'Judge of the Ice Barrier', '冰结界的净玻璃', '氷結界の浄玻璃', 'Effect Monster', 'Warrior', 'WATER', 4, 1800, 900, '这个卡名的②③的效果1回合各能使用1次。 ①：只要自己场上有其他的「冰结界」怪兽存在，每次对方支付基本分来让卡的效果发动让对方失去500基本分。 ②：以自己墓地的「冰结界」怪兽以及对方墓地的卡各最多2张为对象才能发动。那些卡回到卡组。 ③：自己场上有「冰结界」怪兽存在的场合，把墓地的这张卡除外，以场上1只攻击表示怪兽为对象才能发动。那只怪兽变成守备表示。'),
(57774843, 'Judgment Dragon', '裁决之龙', '裁きの龍', 'Effect Monster', 'Dragon', 'LIGHT', 8, 3000, 2600, '这张卡不能通常召唤。自己墓地的「光道」怪兽是4种类以上的场合才能特殊召唤。 ①：支付1000基本分才能发动。场上的其他卡全部破坏。 ②：自己结束阶段发动。从自己卡组上面把4张卡送去墓地。'),
(55256016, 'Judgment of Anubis', '阿努比斯的裁决', 'アヌビスの裁き', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '丢弃1张手卡。对方控制的持有「把场上的魔法·陷阱卡破坏」效果的魔法卡的发动和效果无效并破坏。那之后，可以把对方场上1只表侧表示的怪兽破坏，给与对方玩家那只怪兽的攻击力数值的伤害。'),
(93595154, 'Judgment of the Branded', '烙印之裁决', '烙印の裁き', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：以自己场上1只8星以上的融合怪兽为对象才能发动。持有那只怪兽的攻击力以上的攻击力的对方场上的怪兽全部破坏。 ②：这张卡为让「阿不思的落胤」的效果发动而被送去墓地的回合的结束阶段才能发动。这张卡在自己场上盖放。'),
(4869446, 'Judgment of the Desert', '沙漠的裁决', '砂漠の裁き', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '表侧表示的怪兽不能变更其表示形式。'),
(55948544, 'Judgment of the Pharaoh', '法老的审判', 'ファラオの審判', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把基本分支付一半，从以下效果选择1个才能发动。 ●自己墓地有「友情 YU-JYO」存在的场合，直到回合结束时，对方场上的怪兽的效果无效化，对方不能把怪兽召唤·反转召唤·特殊召唤·盖放，怪兽的效果的发动不能进行并无效化。 ●自己墓地有「团结 UNITY」存在的场合，直到回合结束时，对方场上的魔法·陷阱卡的效果无效化，对方不能把魔法·陷阱卡发动·盖放，魔法·陷阱卡的效果的发动不能进行并无效化。'),
(85080048, 'Judgment of Thunder', '雷之裁决', '雷の裁き', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有雷族怪兽召唤·反转召唤·特殊召唤时，以对方场上1张卡为对象才能发动。那张对方的卡破坏。'),
(41659072, 'Judgment, the Dragon of Heaven', '炽天龙 裁决', '熾天龍 ジャッジメント', 'Synchro Monster', 'Dragon', 'LIGHT', 8, 3000, 2600, '调整＋调整以外的怪兽1只以上 这张卡同调召唤的场合，同调素材怪兽必须全部是相同属性的怪兽。 ①：自己墓地有调整4种类以上存在，这张卡是已同调召唤的场合，1回合1次，把基本分支付一半才能发动。这张卡以外的场上的卡全部破坏。这个效果的发动后，直到回合结束时自己不是龙族怪兽不能特殊召唤。 ②：自己结束阶段发动。从自己卡组上面把4张卡除外。'),
(42851643, 'Jumbo Drill', '穿孔重机 凿岩台车', '穿孔重機ドリルジャンボ', 'Effect Monster', 'Machine', 'EARTH', 4, 1800, 100, '这张卡召唤成功时，可以把自己场上的全部机械族怪兽的等级上升1星。这张卡向守备表示怪兽攻击时，若攻击力超过那个守备力，给与对方基本分那个数值的战斗伤害。此外，这张卡攻击的场合，伤害步骤结束时变成守备表示。'),
(73490417, 'Jungle Dweller', '密林的潜伏者', '密林に潜む者', 'Effect Monster', 'Fiend', 'DARK', 8, 2500, 1800, '这张卡不能通常召唤，用卡的效果才能特殊召唤。这个卡名的①③的效果1回合各能使用1次。 ①：从自己墓地把1只光·暗属性怪兽除外才能发动。这张卡从手卡特殊召唤。 ②：只要场地区域有2张卡存在，对方不能把这张卡作为效果的对象。 ③：这张卡被对方破坏的场合才能发动。自己的墓地·除外状态的最多2张场地魔法卡回到卡组。那之后，可以把最多有回去数量的对方场上的卡破坏。'),
(25148255, 'Junk Anchor', '废品抓锚', 'ジャンク・アンカー', 'Tuner Monster', 'Warrior', 'EARTH', 2, NULL, NULL, '这张卡可以作为「同调士」调整的代替而成为同调素材。 ①：1回合1次，丢弃1张手卡，以调整以外的自己墓地1只「废品」怪兽为对象才能发动。那只怪兽特殊召唤，只用那只怪兽和这张卡为素材，把以「同调士」调整为素材的1只同调怪兽同调召唤。那个时候的同调素材怪兽不去墓地而除外。'),
(42810973, 'Junk Archer', '废品弓箭手', 'ジャンク・アーチャー', 'Synchro Monster', 'Warrior', 'EARTH', 7, 2300, 2000, '「废品同调士」＋调整以外的怪兽1只以上 1回合1次，选择对方场上存在的1只怪兽才能发动。选择的怪兽从游戏中除外。这个效果除外的怪兽在这个回合的结束阶段时以相同表示形式回到对方场上。'),
(91215724, 'Junk Armor', '废品装甲', 'ジャンク・アーマー', 'Effect Monster', 'Warrior', 'EARTH', 2, 600, 1200, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡用抽卡以外的方法加入手卡的场合才能发动。这张卡特殊召唤。 ②：只要这张卡在怪兽区域存在，对方不能把原本卡名包含「战士」或「星尘」的自己场上的同调怪兽作为效果的对象。 ③：把这张卡解放才能发动。从卡组把1只「废品铠甲」以外的「废品」怪兽或「同调士」怪兽守备表示特殊召唤。'),
(79068663, 'Junk Barrage', '废品坠击', 'ジャンク・アタック', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '装备怪兽战斗破坏怪兽送去墓地时，给与对方基本分破坏怪兽的攻击力一半数值的伤害。'),
(59771339, 'Junk Berserker', '废品狂战鬼', 'ジャンク・バーサーカー', 'Synchro Monster', 'Warrior', 'WIND', 7, 2700, 1800, '「废品同调士」＋调整以外的怪兽1只以上 把自己墓地存在的1只名字带有「废品」的怪兽从游戏中除外，选择对方场上表侧表示存在的1只怪兽发动。选择的对方怪兽的攻击力下降除外的怪兽的攻击力数值。此外，这张卡向守备表示怪兽攻击的场合，不进行伤害计算把那只怪兽破坏。'),
(51855378, 'Junk Blader', '废品剑士', 'ジャンク・ブレーダー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 1000, '可以把自己墓地存在的1只名字带有「废品」的怪兽从游戏中除外，这张卡的攻击力直到结束阶段时上升400。'),
(37745919, 'Junk Box', '废料箱', 'ジャンクBOX', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只4星以下的「变形斗士」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合的结束阶段破坏。'),
(43436049, 'Junk Breaker', '废品破坏者', 'ジャンク・ブレイカー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 1000, '①：这张卡召唤成功的回合的自己主要阶段，把这张卡解放才能发动。场上的全部表侧表示怪兽的效果直到回合结束时无效。'),
(1006081, 'Junk Changer', '废品变换者', 'ジャンク・チェンジャー', 'Tuner Monster', 'Warrior', 'EARTH', 3, 1500, 900, '「废品变更者」的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，可以以场上1只「废品」怪兽为对象从以下效果选择1个发动。 ●作为对象的怪兽的等级上升1星。 ●作为对象的怪兽的等级下降1星。'),
(58242947, 'Junk Collector', '废品收集者', 'ジャンク・コレクター', 'Effect Monster', 'Warrior', 'LIGHT', 5, 1000, 2200, '把场上表侧表示存在的这张卡和自己墓地存在的1张通常陷阱卡从游戏中除外发动。这张卡的效果变成和为这个效果发动而从游戏中除外的通常陷阱卡的效果相同。这个效果在对方回合也能发动。'),
(37337327, 'Junk Connector', '废品连结者', 'ジャンク・コネクター', 'Link Monster', 'Warrior', 'DARK', NULL, 1700, NULL, '包含调整1只以上的战士族·机械族的效果怪兽2只 ①：1回合1次，自己·对方的主要阶段以及战斗阶段才能发动。只用这张卡所连接区的怪兽为素材作同调召唤。 ②：连接召唤的这张卡被战斗或者对方的效果破坏送去墓地的场合才能发动。从额外卡组把1只「废品」同调怪兽当作同调召唤作特殊召唤。'),
(11069680, 'Junk Converter', '废品转换者', 'ジャンク・コンバーター', 'Effect Monster', 'Warrior', 'EARTH', 2, 400, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把这张卡和1只调整丢弃才能发动。从卡组把1只「同调士」怪兽加入手卡。 ②：这张卡作为同调素材送去墓地的场合，以自己墓地1只调整为对象才能发动。那只怪兽守备表示特殊召唤。这个回合，这个效果特殊召唤的怪兽的效果不能发动。'),
(68120130, 'Junk Defender', '废品防御者', 'ジャンク・ディフェンダー', 'Effect Monster', 'Warrior', 'EARTH', 3, 500, 1800, '对方怪兽的直接攻击宣言时，这张卡可以从手卡特殊召唤。此外，1回合1次，可以把这张卡的守备力直到结束阶段时上升300。这个效果在对方回合也能发动。'),
(74860293, 'Junk Destroyer', '废品破坏神', 'ジャンク・デストロイヤー', 'Synchro Monster', 'Warrior', 'EARTH', 8, 2600, 2500, '「废品同调士」＋调整以外的怪兽1只以上 ①：这张卡同调召唤成功时，以最多有那些作为同调素材的怪兽之内除调整以外的怪兽数量的场上的卡为对象才能发动。那些卡破坏。'),
(3121655, 'Junk Dragonlet', '废品插座龙', 'ジャンク・ドラゴンセント', 'Effect Monster', 'Machine', 'EARTH', 5, 2100, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己场上有同调怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：自己的同调怪兽的攻击宣言时，把墓地的这张卡除外才能发动。那只自己怪兽的攻击力直到回合结束时上升800。'),
(56410040, 'Junk Forward', '废品先锋', 'ジャンク・フォアード', 'Effect Monster', 'Warrior', 'EARTH', 3, 900, 1500, '自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。'),
(37993923, 'Junk Gardna', '废品守卫者', 'ジャンク・ガードナー', 'Synchro Monster', 'Warrior', 'EARTH', 6, 1400, 2600, '「废品同调士」＋调整以外的怪兽1只以上 1回合1次，可以选择对方场上存在的1只怪兽，把表示形式变更。这个效果在对方回合也能发动。此外，这张卡从场上送去墓地的场合，可以选择场上存在的1只怪兽，把表示形式变更。'),
(34492631, 'Junk Giant', '废品巨人', 'ジャンク・ジャイアント', 'Effect Monster', 'Machine', 'EARTH', 6, 2000, 2400, '①：对方场上有5星以上的怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡为素材的同调召唤不会被无效化，在那次同调召唤成功时对方不能把魔法·陷阱·怪兽的效果发动。'),
(39520293, 'Junk Mail', '废品盔甲', 'ジャンク・メイル', 'Tuner Monster', 'Warrior', 'EARTH', 1, 400, 100, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡为同调素材的同调怪兽不会被战斗破坏。 ②：这个回合没有送去墓地的这张卡在墓地存在，原本卡名包含「战士」、「同调士」、「星尘」之内任意种的同调怪兽在自己场上存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(73218792, 'Junk Meister', '废品大师', 'ジャンク・マイスター', 'Effect Monster', 'Warrior', 'EARTH', 4, 100, 2300, '这个卡名的①②③的效果1回合各能使用1次。 ①：把额外卡组1只「战士」、「星尘」同调怪兽给对方观看才能发动。这张卡从手卡特殊召唤。这个回合，自己不是同调怪兽不能从额外卡组特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把「废品大王」以外的1张「废品」卡加入手卡。 ③：以自己场上1只「废品」怪兽为对象才能发动。那只怪兽的等级下降最多2星。'),
(67968069, 'Junk Puppet', '废品傀偶', 'ジャンク・パペット', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己墓地1只「机关傀儡」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(78922939, 'Junk Servant', '废品仆从', 'ジャンク・サーバント', 'Effect Monster', 'Warrior', 'EARTH', 4, 1500, 1000, '自己场上有名字带有「废品」的怪兽表侧表示存在的场合，这张卡可以从手卡特殊召唤。'),
(26387390, 'Junk Signal', NULL, NULL, 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, NULL),
(56294501, 'Junk Sleep', '废品睡眠', 'ジャンクスリープ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：对方对怪兽的召唤·特殊召唤成功的场合才能发动。自己场上的里侧守备表示怪兽全部变成表侧攻击表示。 ②：自己·对方的结束阶段才能发动。自己场上的怪兽全部变成里侧守备表示。'),
(77075360, 'Junk Speeder', '废品增速者', 'ジャンク・スピーダー', 'Synchro Monster', 'Warrior', 'WIND', 5, 1800, 1000, '「同调士」调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动（这个效果发动的回合，自己不是同调怪兽不能从额外卡组特殊召唤）。从卡组把「同调士」调整尽可能守备表示特殊召唤（相同等级最多1只）。 ②：这个回合同调召唤的这张卡和怪兽进行战斗的攻击宣言时才能发动。这张卡的攻击力直到回合结束时变成原本攻击力的2倍。'),
(63977008, 'Junk Synchron', '废品同步士', 'ジャンク・シンクロン', 'Tuner Monster', 'Warrior', 'DARK', 3, 1300, 500, '①：这张卡召唤时，以自己墓地1只2星以下的怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(60800381, 'Junk Warrior', '废品战士', 'ジャンク・ウォリアー', 'Synchro Monster', 'Warrior', 'DARK', 5, 2300, 1300, '「废品同调士」＋调整以外的怪兽1只以上 ①：这张卡同调召唤的场合发动。这张卡的攻击力上升自己场上的2星以下的怪兽的攻击力的合计数值。'),
(16327715, 'Junk Warrior Extreme', '废品战士・极致', 'ジャンク・ウォリアー・エクストリーム', 'Synchro Monster', 'Warrior', 'DARK', 8, 2900, 2300, '「废品同调士」＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从自己墓地把2星以下的怪兽尽可能特殊召唤，这个回合，那些怪兽的效果不能发动。这个效果的发动后，直到回合结束时自己只能有1次特殊召唤。 ②：这张卡战斗破坏对方怪兽时，把这张卡除外才能发动。从额外卡组把1只「废品」同调怪兽当作同调召唤作特殊召唤。'),
(23219323, 'Junk Warrior/Assault Mode', '废品战士／爆裂', 'ジャンク・ウォリアー／バスター', 'Effect Monster', 'Warrior', 'DARK', 7, 2800, 1800, '这张卡不能通常召唤，用「爆裂模式」的效果才能特殊召唤。 ①：这张卡的攻击力上升自己场上的「/爆裂体」怪兽数量×1000，这张卡用和怪兽的战斗给与对方的战斗伤害变成2倍。 ②：场上的这张卡不受对方发动的怪兽的效果影响。 ③：这张卡被破坏的场合，以自己墓地1只「废品战士」为对象才能发动。那只怪兽回到额外卡组。那之后，可以把那只怪兽当作同调召唤作特殊召唤。'),
(38491199, 'Junkuriboh', '废品栗子球', 'ジャンクリボー', 'Effect Monster', 'Machine', 'EARTH', 1, 300, 200, '①：给与自己伤害的魔法·陷阱·怪兽的效果由对方发动时，把自己的手卡·场上的这张卡送去墓地才能发动。那个发动无效并破坏。'),
(5914858, 'Junora the Power Patron of Tuning', '调狱神 朱诺拉', '調獄神ジュノーラ', 'Synchro Monster', 'Fiend', 'FIRE', 10, 3100, 3800, '调整＋调整以外的怪兽2只 这张卡同调召唤的场合，可以把自己的中央的主要怪兽区域1只怪兽当作调整使用。这个卡名的②的效果1回合只能使用1次。 ①：这张卡同调召唤的场合才能发动。对方场上的全部表侧表示卡的效果无效化。 ②：自己·对方回合可以发动。和自己场上的「耀圣」怪兽相同纵列的对方场上的全部怪兽直到回合结束时不能作为融合·同调·超量·连接召唤的素材。'),
(68231287, 'Jupiter the Power Patron of Destruction', '坏狱神 朱庇特', '壊獄神ユピテル', 'XYZ Monster', 'Machine', 'WIND', 10, 3500, 2500, '10星怪兽×3 「坏狱神 朱庇特」1回合1次也能在有装备卡3张以上装备的自己怪兽上面重叠来超量召唤。 ①：这张卡超量召唤的场合才能发动。把这张卡可以装备的装备魔法卡任意数量从自己墓地装备。 ②：有超量怪兽在作为素材中的这张卡的攻击力上升3000。 ③：1回合1次，把这张卡1个超量素材取除才能发动。从自己墓地把1只「终刻」怪兽特殊召唤。那之后，可以把场上1张卡破坏。'),
(59546797, 'Juragedo', '灸拉盖德', 'ジュラゲド', 'Effect Monster', 'Fiend', 'DARK', 4, 1700, 1300, '这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的战斗步骤才能发动。这张卡从手卡特殊召唤，自己回复1000基本分。 ②：把这张卡解放，以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到下个回合的结束时上升1000。这个效果在对方回合也能发动。'),
(78693036, 'Juraishin, the Cursed Thunder God', '咒雷神 宙拉', '呪雷神ジュラ', 'Synchro Monster', 'Psychic', 'EARTH', 11, 3100, 3100, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，每次对方把卡的效果发动，自己回复300基本分。 ②：对方回合，可以支付1500基本分，把这张卡解放，从以下效果选择1个发动。 ●对方场上的表侧表示怪兽全部破坏。 ●对方场上的表侧表示的魔法·陷阱卡全部破坏。'),
(65430834, 'Jurassic Impact', '侏罗纪冲击', 'ジュラシック・インパクト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有恐龙族怪兽2只以上存在，自己基本分比对方少的场合才能发动。场上的怪兽全部破坏，自己受到破坏的怪兽数量×1000伤害。那之后，给与对方为和自己受到的伤害相同数值的伤害。这张卡的发动后，直到下个回合的结束时双方不能把怪兽召唤·特殊召唤。'),
(99531088, 'Jurassic Power', '侏罗纪力量', 'ジュラシック・パワー', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的③的效果1回合只能使用1次。 ①：自己场上的恐龙族怪兽的攻击力上升300。 ②：自己在5星以上的恐龙族怪兽召唤的场合需要的解放可以不用。 ③：从自己的手卡·场上（表侧表示）把1只恐龙族怪兽送去墓地才能发动。从卡组把1只守备力1200的恐龙族怪兽加入手卡。'),
(10080320, 'Jurassic World', '侏罗纪世界', 'ジュラシックワールド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '场上表侧表示存在的恐龙族怪兽的攻击力·守备力上升300。'),
(80727721, 'Jurrac Aeolo', '朱罗纪・异特龙', 'ジュラック・アウロ', 'Tuner Monster', 'Dinosaur', 'FIRE', 1, 200, 200, '①：把这张卡解放，以「朱罗纪异特龙」以外的自己墓地1只4星以下的「朱罗纪」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(52553102, 'Jurrac Astero', '朱罗纪・小行星龙', 'ジュラック・アステロ', 'Synchro Monster', 'Dinosaur', 'FIRE', 10, 2500, 2300, '调整＋调整以外的恐龙族怪兽1只以上 ①：这张卡同调召唤的场合才能发动。从自己的卡组·墓地把1张「朱罗纪」魔法·陷阱卡在自己场上盖放。 ②：1回合1次，对方把怪兽特殊召唤之际，从自己墓地把2只恐龙族怪兽除外才能发动。那个无效，那些怪兽破坏。 ③：对方回合，从自己墓地把包含这张卡的2只「朱罗纪」怪兽除外才能发动。从额外卡组把1只「朱罗纪陨石兽」当作同调召唤作特殊召唤。'),
(8594079, 'Jurrac Brachis', '朱罗纪腕龙', 'ジュラック・ブラキス', 'Tuner Monster', 'Dinosaur', 'FIRE', 3, 1000, 1000, '场上有这张卡以外的名字带有「朱罗纪」的怪兽表侧表示存在的场合，这张卡不会被战斗破坏。'),
(17948378, 'Jurrac Dino', '朱罗纪・暴仔龙', 'ジュラック・デイノ', 'Tuner Monster', 'Dinosaur', 'FIRE', 3, 1700, 800, '①：这张卡战斗破坏对方怪兽的回合的结束阶段，把自己场上1只「朱罗纪」怪兽解放才能发动。自己抽2张。'),
(43332022, 'Jurrac Gallim', '朱罗纪・似鸡龙', 'ジュラック・ガリム', 'Tuner Monster', 'Dinosaur', 'FIRE', 2, 1200, NULL, '①：这张卡被战斗破坏送去墓地的场合发动。对方可以选1张手卡丢弃让这个效果无效。没丢弃的场合，把让这张卡破坏的怪兽破坏。'),
(80032567, 'Jurrac Giganoto', '朱罗纪・巨兽龙', 'ジュラック・ギガノト', 'Synchro Monster', 'Dinosaur', 'FIRE', 7, 2100, 1800, '调整＋调整以外的恐龙族怪兽1只以上 ①：只要这张卡在怪兽区域存在，自己场上的「朱罗纪」怪兽的攻击力上升自己墓地的「朱罗纪」怪兽数量×200。'),
(11012887, 'Jurrac Guaiba', '朱罗纪・瓜巴龙', 'ジュラック・グアイバ', 'Effect Monster', 'Dinosaur', 'FIRE', 4, 1700, 400, '①：这张卡战斗破坏对方怪兽时才能发动。从卡组把1只攻击力1700以下的「朱罗纪」怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击宣言。'),
(16111820, 'Jurrac Herra', '朱罗纪・艾雷拉龙', 'ジュラック・ヘレラ', 'Effect Monster', 'Dinosaur', 'FIRE', 6, 2300, 1500, '自己场上守备表示存在的「朱罗纪艾雷拉龙」以外的名字带有「朱罗纪」的怪兽被战斗破坏送去墓地时，这张卡可以从手卡或者墓地特殊召唤。'),
(71106375, 'Jurrac Iguanon', '朱罗纪禽龙', 'ジュラック・イグアノン', 'Effect Monster', 'Dinosaur', 'FIRE', 4, 1700, 700, '这张卡战斗破坏对方怪兽的场合，可以让对方场上盖放的1张卡回到手卡。'),
(5479217, 'Jurrac Impact', '朱罗纪冲击', 'ジュラック・インパクト', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有攻击力2500以上的恐龙族怪兽存在的场合才能发动。场上的卡全部破坏。'),
(93170499, 'Jurrac Megalo', '朱罗纪・斑龙', 'ジュラック・メガロ', 'Tuner Monster', 'Dinosaur', 'FIRE', 1, 500, 1300, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己场上有恐龙族怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：自己主要阶段才能发动。从手卡选包含「朱罗纪」卡的2张卡丢弃。那之后，自己抽2张。 ③：这张卡被战斗·效果破坏的场合才能发动。从卡组·额外卡组把「朱罗纪斑龙」以外的1只「朱罗纪」怪兽送去墓地。'),
(17548456, 'Jurrac Meteor', '朱罗纪・陨星龙', 'ジュラック・メテオ', 'Synchro Monster', 'Dinosaur', 'FIRE', 10, 2800, 2000, '「朱罗纪」调整＋调整以外的恐龙族怪兽2只以上 ①：这张卡同调召唤的场合发动。场上的卡全部破坏。那之后，可以从自己墓地把1只调整特殊召唤。'),
(36717258, 'Jurrac Monoloph', '朱罗纪・单冠龙', 'ジュラック・モノロフ', 'Tuner Monster', 'Dinosaur', 'FIRE', 3, 1500, 1200, '①：这张卡可以向对方怪兽全部各作1次攻击。'),
(23927545, 'Jurrac Protops', '朱罗纪原角龙', 'ジュラック・プロトプス', 'Effect Monster', 'Dinosaur', 'FIRE', 4, 1700, 1200, '这张卡的攻击力上升对方场上存在的怪兽数量×100的数值。'),
(45711266, 'Jurrac Ptera', '朱罗纪翼龙', 'ジュラック・プティラ', 'Effect Monster', 'Dinosaur', 'FIRE', 3, 800, 1500, '这张卡被攻击的场合，伤害计算后攻击怪兽回到手卡。这张卡的守备力上升这个效果回到手卡的怪兽等级×100的数值。'),
(44689688, 'Jurrac Spinos', '朱罗纪・棘龙', 'ジュラック・スピノス', 'Effect Monster', 'Dinosaur', 'FIRE', 7, 2600, 1700, '这张卡战斗破坏对方怪兽送去墓地时，在对方场上把1只「棘龙衍生物」（恐龙族·炎·1星·攻300/守0）攻击表示特殊召唤。'),
(48411996, 'Jurrac Stauriko', '朱罗纪南十字龙', 'ジュラック・スタウリコ', 'Effect Monster', 'Dinosaur', 'FIRE', 2, 500, 400, '这张卡被战斗破坏的场合，在自己场上把2只「朱罗纪衍生物」（恐龙族·炎·1星·攻0/守0）守备表示特殊召唤。这衍生物不能为名字带有「朱罗纪」的怪兽以外的上级召唤而解放。'),
(20568404, 'Jurrac Stego', '朱罗纪・剑龙', 'ジュラック・スティゴ', 'Effect Monster', 'Dinosaur', 'FIRE', 4, 1700, 900, '这个卡名的①的效果1回合只能使用1次。 ①：自己主要阶段才能发动。自己场上1张卡破坏，从卡组把1只恐龙族怪兽送去墓地。那之后，可以直到等级合计变成和从卡组送去墓地的怪兽相同为止从手卡·卡组把「朱罗纪剑龙」以外的「朱罗纪」怪兽无视召唤条件特殊召唤。这个回合，自己不是恐龙族怪兽不能特殊召唤。 ②：这张卡被战斗破坏时才能发动。场上1张表侧表示卡回到手卡。'),
(85028288, 'Jurrac Titano', '朱罗纪・泰坦龙', 'ジュラック・タイタン', 'Effect Monster', 'Dinosaur', 'FIRE', 9, 3000, 2800, '这张卡不能特殊召唤。 ①：双方不能把场上的这张卡作为陷阱·怪兽的效果的对象。 ②：1回合1次，从自己墓地把1只攻击力1700以下的「朱罗纪」怪兽除外才能发动。这张卡的攻击力直到回合结束时上升1000。'),
(48411997, 'Jurrac Token', '朱罗纪南十字龙', 'ジュラック・スタウリコ', 'Token', 'Dinosaur', NULL, NULL, NULL, NULL, NULL),
(62701967, 'Jurrac Tyrannus', '朱罗纪暴龙', 'ジュラック・ティラヌス', 'Effect Monster', 'Dinosaur', 'FIRE', 7, 2500, 1400, '可以把自己场上存在的1只恐龙族怪兽解放，这张卡的攻击力上升500。这张卡战斗破坏对方怪兽送去墓地时，这张卡的攻击力上升300。'),
(59312550, 'Jurrac Velo', '朱罗纪・迅猛龙', 'ジュラック・ヴェロー', 'Effect Monster', 'Dinosaur', 'FIRE', 4, 1700, 1000, '①：自己场上的攻击表示的这张卡被战斗破坏送去墓地时才能发动。从卡组把1只攻击力1700以下的「朱罗纪」怪兽特殊召唤。'),
(65961683, 'Jurrac Velphito', '朱罗纪・伶盗龙', 'ジュラック・ヴェルヒプト', 'Synchro Monster', 'Dinosaur', 'FIRE', 5, -1, -1, '调整＋调整以外的恐龙族怪兽1只以上 ①：这张卡的攻击力·守备力变成作为这张卡的同调素材的怪兽的原本攻击力合计数值。 ②：这张卡向里侧守备表示怪兽攻击的伤害步骤开始时才能发动。那只里侧守备表示怪兽破坏。'),
(89948817, 'Jurrac Volcano', '朱罗纪喷发', 'ジュラック・ヴォルケーノ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己主要阶段才能发动。自己场上1只恐龙族怪兽破坏，从卡组把1只「朱罗纪」怪兽特殊召唤。 ②：对方把怪兽特殊召唤的场合，若这个回合对方是已把怪兽的效果4次以上发动则能发动。从额外卡组把1只「朱罗纪陨石兽」当作同调召唤作特殊召唤。 ③：自己场上的「朱罗纪」怪兽被效果破坏的场合，可以作为代替把自己墓地1只恐龙族怪兽除外。'),
(24068492, 'Just Desserts', '自业自得', '自業自得', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：给与对方为对方场上的怪兽数量×500伤害。'),
(62271284, 'Justi-Break', '正义雷破', 'ジャスティブレイク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上的通常怪兽为攻击对象的对方怪兽的攻击宣言时才能发动。表侧攻击表示存在的通常怪兽以外的场上的怪兽全部破坏。'),
(26842483, 'Justice Bringer', '正义使者', 'ジャスティス・ブリンガー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1700, 1000, '对方场上存在的特殊召唤的怪兽的效果发动时才能发动。那次发动无效。这个效果1回合只能使用1次。'),
(26732909, 'Justice of Prophecy', '魔导教士 朱丝蒂', '魔導教士 システィ', 'Effect Monster', 'Spellcaster', 'EARTH', 3, 1600, 800, '自己把名字带有「魔导书」的魔法卡发动的自己回合的结束阶段时，把场上的这张卡从游戏中除外才能发动。从卡组把1只光属性或者暗属性的魔法师族·5星以上的怪兽和1张名字带有「魔导书」的魔法卡加入手卡。「魔导教士 朱丝蒂」的效果1回合只能使用1次。'),
(60410769, 'Jutte Fighter', '十手武士', 'ジュッテ・ナイト', 'Tuner Monster', 'Warrior', 'EARTH', 2, 700, 900, '1回合只有1次，可以把对方场上表侧攻击表示存在的1只怪兽变成表侧守备表示。'),
(47960073, 'K9-04 Noroi', 'K9－04号 咒', 'K９－０４号 咒', 'Effect Monster', 'Machine', 'EARTH', 5, 2200, 1500, '这个卡名的②③的效果1回合各能使用1次。 ①：对方手卡是2张以上的场合，这张卡可以不用解放作召唤。 ②：这张卡召唤的场合才能发动。从卡组把1只机械族以外的「K9」怪兽特殊召唤。只要这个效果特殊召唤的怪兽在自己场上表侧表示存在，自己不是「K9」怪兽不能从额外卡组特殊召唤。 ③：把自己场上1张表侧表示的「K9」卡送去墓地才能发动。把对方手卡全部确认。'),
(27420823, 'K9-17 "Ripper"', 'K9－17号 “割裂者”', 'K９－１７号 “Ripper”', 'XYZ Monster', 'Warrior', 'WIND', 5, 2300, 1800, '5星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡1个超量素材取除才能发动。从卡组把1张「K9」卡加入手卡。这个回合对方是已把怪兽的效果发动的场合，可以再从自己的卡组·墓地把1张「K9」速攻魔法卡在自己场上盖放。 ②：对方把手卡·墓地的怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个效果无效。'),
(92248362, 'K9-17 Izuna', 'K9－17号 饭纲', 'K９－１７号 イヅナ', 'Effect Monster', 'Warrior', 'EARTH', 5, 2100, 1600, '这个卡名的②③的效果1回合各能使用1次。 ①：对方手卡是2张以上的场合，这张卡可以不用解放作召唤。 ②：对方把手卡·墓地的怪兽的效果发动的自己·对方回合的主要阶段才能发动。这张卡从手卡特殊召唤。 ③：这张卡召唤·特殊召唤的场合才能发动。从卡组把「K9-17号 饭纲」以外的1张「K9」卡送去墓地。'),
(28642461, 'K9-66a Jokul', 'K9－66a号 冰精', 'K９－６６a号 ヨクル', 'Effect Monster', 'Aqua', 'DARK', 5, 2000, 1900, '这个卡名的②③的效果1回合各能使用1次。 ①：对方手卡是2张以上的场合，这张卡可以不用解放作召唤。 ②：把手卡的这张卡和手卡1只5星怪兽给对方观看才能发动。那2只特殊召唤。这个效果特殊召唤的怪兽不能作为光属性超量怪兽的超量召唤的素材。 ③：自己主要阶段才能发动。从卡组把1只水族以外的「K9」怪兽加入手卡。'),
(55031170, 'K9-66b Lantern', 'K9－66b号 灯笼', 'K９－６６b号 ランタン', 'Effect Monster', 'Pyro', 'DARK', 5, 2000, 1900, '这个卡名的②③的效果1回合各能使用1次。 ①：对方手卡是2张以上的场合，这张卡可以不用解放作召唤。 ②：这张卡在手卡存在的场合，以炎族以外的自己墓地1只5星「K9」怪兽为对象才能发动。那只怪兽和这张卡特殊召唤。这个效果特殊召唤的怪兽不能作为光属性超量怪兽的超量召唤的素材。 ③：自己主要阶段才能发动。从卡组把1张「K9」魔法·陷阱卡加入手卡。'),
(67515699, 'K9-66X "Jacks"', 'K9－666号 “结克”', 'K９－６６６号 “Jacks”', 'XYZ Monster', 'Fiend', 'DARK', 5, 2600, 2500, '5星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：这张卡超量召唤的场合或者对方把手卡·墓地的怪兽的效果发动的场合，把这张卡1个超量素材取除，以场上1只怪兽为对象才能发动。那只怪兽破坏。 ②：有这张卡在作为超量素材中的「K9」超量怪兽得到以下效果。 ●对方把手卡·墓地的怪兽的效果发动的回合，这张卡给与对方的战斗伤害变成2倍。'),
(26585784, 'K9-EW Special Release Experiment', 'K9－EW 特殊解除实验', 'K９－EW特殊解除実験', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·墓地把1只「K9」怪兽特殊召唤。那之后，可以把1只「K9」超量怪兽在这个效果特殊召唤的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。这个效果从额外卡组特殊召唤的怪兽在下个回合的结束阶段破坏。 ②：自己·对方的结束阶段，把墓地的这张卡除外，以自己墓地1张「K9」速攻魔法卡为对象才能发动。那张卡在自己场上盖放。'),
(27308231, 'K9-LC Release Restraint', 'K9－LC 拘束解除', 'K９－LC拘束解除', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「K9」超量怪兽或者5阶超量怪兽为对象才能发动。和那只自己怪兽卡名不同的1只「K9」超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。 ②：自己的「K9」怪兽进行战斗的回合的战斗阶段结束时才能发动。墓地的这张卡在自己场上盖放。'),
(54919528, 'K9-ØØ "Hound"', 'K9－ØØ号 “猎手”', 'K９－ØØ号 “Hound”', 'XYZ Monster', 'Beast-Warrior', 'LIGHT', 5, 2500, 2500, '5星怪兽×2 ①：这张卡在特殊召唤的回合不会被战斗以及对方的效果破坏。 ②：只要这张卡在怪兽区域存在，每次对方把怪兽的效果发动，这张卡的攻击力上升500。 ③：自己·对方的准备阶段，把这张卡1个超量素材取除，以场上1张卡为对象才能发动。那张卡除外。'),
(91025875, 'K9-ØØ Lupis', 'K9－ØØ号 天狼', 'K９－ØØ号 ルプス', 'Effect Monster', 'Beast-Warrior', 'EARTH', 5, 2300, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：对方把手卡·墓地的怪兽的效果发动的自己·对方回合的主要阶段才能发动。这张卡从手卡·墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：对方回合才能发动。用包含这张卡的自己场上的怪兽为素材进行超量召唤。 ③：持有这张卡作为素材中的超量怪兽得到以下效果。 ●对方不能把这张卡作为效果的对象。'),
(31286915, 'K9-X "Ripper/M"', 'K9－EX “割裂者／千”', 'K９－EX “Ripper／M”', 'XYZ Monster', 'Beast', 'WIND', 9, 3100, 2600, '9星怪兽×2 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡用「K9」魔法·陷阱卡的效果特殊召唤的场合，以对方的墓地·除外状态的最多2张卡为对象才能发动。那些卡回到卡组。 ②：这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ③：对方把怪兽的效果发动时，把这张卡2个超量素材取除才能发动。那个效果无效。那之后，场上的卡全部破坏。'),
(90303227, 'K9-X "Werewolf"', 'K9－EX “狼人”', 'K９－EX “Werewolf”', 'XYZ Monster', 'Beast-Warrior', 'LIGHT', 9, 3300, 2500, '9星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：持有超量素材的这张卡在同1次的战斗阶段中可以作出最多有那个数量的攻击。 ②：对方把效果发动时，可以把这张卡1个超量素材取除，发动回合的以下效果发动。 ●自己回合：对方的场上以及墓地的卡各最多1张除外。 ●对方回合：把对方手卡确认，选那之内的1张直到结束阶段表侧除外。'),
(53792930, 'K9-X Forced Release', 'K9－EX 强制解除', 'K９－EX強制解除', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，以自己场上1只「K9」超量怪兽为对象才能发动。和那只自己怪兽卡名不同的1只「K9」超量怪兽在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤。那之后，可以把对方场上1张卡破坏。 ②：自己的「K9」怪兽进行战斗的回合的战斗阶段结束时才能发动。墓地的这张卡在自己场上盖放。'),
(52768103, 'KA-2 Des Scissors', 'KA-2 死亡钳', 'KA－２ デス・シザース', 'Effect Monster', 'Machine', 'DARK', 4, 1000, 1000, '这张卡战斗破坏怪兽并将其送去墓地时，对对方基本分造成数值等同于被破坏怪兽等级×500点的伤害。'),
(51934376, 'Kabazauls', '打大喷嚏的河马龙', '大くしゃみのカバザウルス', 'Normal Monster', 'Dinosaur', 'WATER', 4, 1700, 1500, '拥有巨大身体的河马怪兽。从其巨大的身体打出的喷嚏，可以匹敌台风。'),
(7541475, 'Kabuki Dragon', '歌舞伎龙', 'カブキ・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2300, 2100, '①：1回合1次，自己怪兽向对方怪兽攻击的伤害计算前才能发动。那只对方怪兽的表示形式变更。 ②：1回合1次，对方怪兽向自己怪兽攻击的伤害计算前才能发动。那只自己怪兽的表示形式变更。'),
(69069911, 'Kachi Kochi Dragon', '硬梆龙', 'カチコチドラゴン', 'XYZ Monster', 'Dragon', 'EARTH', 4, 2100, 1300, '4星怪兽×2 这张卡战斗破坏对方怪兽送去墓地时，可以把这张卡1个超量素材取除，只有1次继续攻击。这个效果1回合只能使用1次。'),
(19353570, 'Kagemucha Knight', '影无茶骑士', '影無茶ナイト', 'Effect Monster', 'Warrior', 'DARK', 3, NULL, NULL, '自己对3星怪兽的召唤成功时，这张卡可以从手卡特殊召唤。这张卡不能作为同调素材。'),
(15401633, 'Kagemusha of the Blue Flame', '紫炎之影武者', '紫炎の影武者', 'Normal Monster', 'Warrior', 'EARTH', 2, 800, 400, '侍奉着紫炎的影武者，持有锋利的名刀。'),
(1498130, 'Kagemusha of the Six Samurai', '六武众之影武者', '六武衆の影武者', 'Tuner Monster', 'Warrior', 'EARTH', 2, 400, 1800, '自己场上表侧表示存在的名字带有「六武众」的怪兽1只成为魔法·陷阱·效果怪兽的效果的对象时，可以把那个效果的对象转换为场上表侧表示存在的这张卡。'),
(39972130, 'Kagemusha Raccoon Token', '编号64 古狸三太夫', 'No.64 古狸三太夫', 'Token', 'Beast', NULL, NULL, NULL, NULL, NULL),
(80600490, 'Kageningen', '暗影战士', 'シャドウ・ファイター', 'Normal Monster', 'Warrior', 'DARK', 2, 800, 600, '用实体和影子袭击对方。疏忽的话就会受到夹击的哦。'),
(20065259, 'Kagero the Cannon Ninja', '铳之忍者-火光', '銃の忍者－火光', 'Effect Monster', 'Warrior', 'FIRE', 4, 1600, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤·反转的场合才能发动。从自己的手卡·墓地选「铳之忍者-火光」以外的1只「忍者」怪兽里侧守备表示特殊召唤。 ②：这张卡在墓地存在，只以自己场上的「忍者」卡1张或者里侧守备表示怪兽1只为对象的对方的效果发动时才能发动。这张卡里侧守备表示特殊召唤，那张成为对象的卡回到持有者手卡。'),
(94656263, 'Kagetokage', '影蜥蜴', 'カゲトカゲ', 'Effect Monster', 'Reptile', 'DARK', 4, 1100, 1500, '这张卡不能通常召唤，用这张卡的效果可以特殊召唤。这张卡不能作为同调素材。 ①：自己对4星怪兽的召唤成功时才能发动。这张卡从手卡特殊召唤。'),
(25847467, 'Kahkki, Guerilla of Dark World', '暗黑界的刺客 卡其', '暗黒界の刺客 カーキ', 'Effect Monster', 'Fiend', 'DARK', 2, 300, 500, '①：这张卡被效果从手卡丢弃去墓地的场合，以场上1只怪兽为对象发动。那只怪兽破坏。'),
(39049051, 'Kahyoreigetsu', '歌冰丽月', '歌氷麗月', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡把1只4星以下的天使族·魔法师族·鸟兽族·兽战士族怪兽特殊召唤，把这张卡装备。那之后，可以让场上的龙族怪兽全部回到持有者手卡。 ②：魔法与陷阱区域的表侧表示的这张卡被送去墓地的回合的结束阶段才能发动。从卡组把1张「融合」魔法卡或者1只「寄生融合虫」加入手卡。'),
(71614230, 'Kai-Den Kendo Spirit', '剑道魂 皆传', 'ケンドウ魂 KAI－DEN', 'Spirit Monster', 'Warrior', 'WIND', 5, 2400, 1000, '①：这张卡召唤成功时才能发动。选自己的灵摆区域1张卡，和那张卡相同纵列的对方的卡全部送去墓地。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到持有者手卡。'),
(34627841, 'Kaibaman', '正义的伙伴 海马人', '正義の味方 カイバーマン', 'Effect Monster', 'Warrior', 'LIGHT', 3, 200, 700, '把这张卡解放才能发动。从手卡把1只「青眼白龙」特殊召唤。'),
(67768675, 'Kaibaman the Legend', '正义的传说 海马人', '正義の伝説 カイバーマン', 'Tuner Monster', 'Warrior', 'LIGHT', 1, 200, 700, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。选自己的手卡·卡组·场上（表侧表示）·墓地3张「青眼白龙」，给双方确认。那之后，从自己的手卡·卡组·墓地把1只「青眼白龙」特殊召唤。 ②：这张卡在墓地存在的状态，自己把「青眼白龙」特殊召唤的场合，把这张卡除外才能发动。从卡组把1只「青眼」怪兽加入手卡。'),
(81057455, 'Kaiju Capture Mission', '坏兽捕获大作战', '壊獣捕獲大作戦', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '「坏兽捕获大作战」的②的效果1回合只能使用1次。 ①：1回合1次，以场上1只「坏兽」怪兽为对象才能发动。那只怪兽变成里侧守备表示。那之后，给这张卡放置1个坏兽指示物（最多3个）。 ②：这张卡被对方的效果破坏送去墓地的场合才能发动。自己从卡组抽2张。'),
(60822251, 'Kaiki the Unity Star', '天融星 怪奇', '天融星カイキ', 'Effect Monster', 'Warrior', 'LIGHT', 5, 1000, 2100, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合，支付500基本分才能发动。从自己的手卡·场上把战士族融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：对方回合，持有和原本攻击力不同攻击力的5星以上的战士族怪兽在自己场上存在的场合才能发动。这张卡从墓地特殊召唤。'),
(20904475, 'Kairo Ryu-Ge Emva', '海瀧龙华－渊轮巴王', '海瀧竜華－淵巴', 'Effect Monster', 'Sea Serpent', 'WATER', 10, 3000, 2000, '这个卡名的①②③的效果1回合各能使用1次。 ①：把这张卡从手卡丢弃才能发动。从卡组把1张「登龙华海泷门」加入手卡。 ②：「海泷龙华-渊巴」以外的怪兽2只以上从手卡·卡组送去墓地的回合的自己主要阶段才能发动。这张卡从墓地特殊召唤。 ③：让自己场上1张表侧表示的「登龙华海泷门」回到卡组最下面才能发动。对方手卡全部除外，对方抽出那个数量。'),
(76634149, 'Kairyu-Shin', '海龙神', '海竜神', 'Normal Monster', 'Sea Serpent', 'WATER', 5, 1800, 1500, '被称为海洋之主的海龙。掀起海啸吞噬一切。'),
(95602345, 'Kairyu-Shin''s Dark Reef', '暗岩的海龙神', '暗岩の海竜神', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：把自己场上1张表侧表示的「海」送去墓地才能发动。从自己的手卡·卡组把有「海」的卡名记述的怪兽或者水属性通常怪兽合计最多2只守备表示特殊召唤（同名卡最多1张）。对方场上有怪兽存在的场合，可以再从手卡·卡组把6星以下的水属性通常怪兽任意数量特殊召唤。这张卡的发动后，直到下次的自己回合的结束时自己不是水属性怪兽不能特殊召唤。'),
(35059553, 'Kaiser Colosseum', '凯撒竞技场', 'カイザーコロシアム', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要自己场上有怪兽存在，对方不能让要变到比那个数量多的怪兽在自身场上出现。'),
(94566432, 'Kaiser Dragon', '帝王龙', 'カイザー・ドラゴン', 'Fusion Monster', 'Dragon', 'LIGHT', 7, 2300, 2000, '「守城的翼龙」＋「妖精龙」'),
(52824910, 'Kaiser Glider', '帝王翔风龙', 'カイザー・グライダー', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2400, 2200, '①：这张卡不会被和相同攻击力的怪兽的战斗破坏。 ②：这张卡被破坏送去墓地的场合，以场上1只怪兽为对象发动。那只怪兽回到持有者手卡。'),
(41002238, 'Kaiser Glider - Golden Burst', '帝王翔风龙-黄金爆风弹', 'カイザー・グライダー－ゴールデン・バースト', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2400, 2200, '这个卡名的①的效果1回合只能使用1次。 ①：把自己场上1只怪兽解放才能发动。这张卡从手卡特殊召唤。这个效果在对方回合也能发动。 ②：这张卡召唤·特殊召唤成功的场合，以对方场上1只表侧表示怪兽为对象才能发动。这张卡的攻击力直到回合结束时变成和那只怪兽的攻击力相同。'),
(17444133, 'Kaiser Sea Horse', '帝王海马', 'カイザー・シーホース', 'Effect Monster', 'Sea Serpent', 'LIGHT', 4, 1700, 1650, '①：光属性怪兽上级召唤的场合，这张卡可以作为2只的数量解放。'),
(6442944, 'Kaiser Sea Snake', '帝王海蛇', 'カイザー・シースネーク', 'Effect Monster', 'Sea Serpent', 'WATER', 8, 2500, 1000, '「帝王海蛇」的①的方法的特殊召唤1回合只能有1次。 ①：对方场上有怪兽存在，自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡用这张卡的①的方法特殊召唤成功时才能发动。从自己的手卡·墓地选1只海龙族·8星怪兽特殊召唤。这个效果特殊召唤的怪兽的攻击力·守备力变成0。 ③：特殊召唤的这张卡的等级变成4星，原本攻击力变成0。'),
(93927067, 'Kaiser Vorse Raider', '血腥魔兽人帝王', 'カイザー・ブラッド・ヴォルス', 'Effect Monster', 'Beast-Warrior', 'DARK', 5, 1900, 1200, '①：自己场上没有怪兽存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡战斗破坏对方怪兽的场合发动。这张卡的攻击力上升500。 ③：这张卡被战斗破坏的场合发动。让把这张卡破坏的怪兽的攻击力下降500。'),
(50834074, 'Kaitoptera', '地狱猛禽龙', 'ヘルカイトプテラ', 'Effect Monster', 'Dinosaur', 'WIND', 4, 1400, 1000, '这个卡名的②③的效果1回合各能使用1次。 ①：对方场上有风属性怪兽以外的表侧表示怪兽2只以上存在的场合，那些对方怪兽不能选择这张卡作为攻击对象。 ②：自己主要阶段才能发动。从卡组把1张「融合」加入手卡。 ③：这张卡被除外的场合才能发动。这张卡特殊召唤。那之后，可以从自己墓地把1张「融合」加入手卡。'),
(25449584, 'Kaiza the Hidden Star', '地葬星 怪座', '地葬星カイザ', 'Effect Monster', 'Warrior', 'EARTH', 5, 1000, 2100, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡可以把自己场上1只光属性或者地属性的战士族怪兽解放从手卡特殊召唤。这个方法特殊召唤的这张卡的攻击力上升解放的怪兽的原本攻击力数值。 ②：从自己墓地把1只战士族怪兽除外才能发动。从卡组把1只光属性或者地属性的战士族怪兽送去墓地。'),
(97317530, 'Kalantosa, Mystical Beast of the Forest', '森之圣兽 月耳草兔', '森の聖獣 カラントーサ', 'Effect Monster', 'Beast', 'EARTH', 2, 200, 1400, '①：这张卡用兽族怪兽的效果特殊召唤成功的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(68928540, 'Kamakiriman', '螳螂杀手', 'カマキラー', 'Normal Monster', 'Insect', 'EARTH', 4, 1150, 1400, '用两把镰刀袭击对方的一种人型螳螂怪兽。'),
(9653271, 'Kaminari Attack', '雷神之怒', '雷神の怒り', 'Fusion Monster', 'Thunder', 'WIND', 5, 1900, 1400, '「耳天使」＋「大雷电球」'),
(97570038, 'Kaminote Blow', '神拳粉碎', 'ゴッドハンド・スマッシュ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上「格斗鼠 吱助」「武僧战士」「武僧大师」内1只以上存在时发动。这个回合和这些怪兽进行战斗的怪兽在伤害步骤结束时破坏。'),
(91712985, 'Kamion, the Timelord', '时械神 卡米恩', '時械神カミオン', 'Effect Monster', 'Fairy', 'EARTH', 10, NULL, NULL, '这张卡不能从卡组特殊召唤。 ①：自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡不会被战斗·效果破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ③：这张卡进行战斗的战斗阶段结束时发动。选对方场上1张卡回到持有者卡组，给与对方500伤害。不能对应这个效果的发动让卡的效果发动。 ④：自己准备阶段发动。这张卡回到持有者卡组。'),
(41544074, 'Kamionwizard', '混沌男巫', 'カオス・ウィザード', 'Fusion Monster', 'Spellcaster', 'DARK', 4, 1300, 1100, '「圣精灵」＋「黑魔族的幕帘」'),
(72439556, 'Kamui, Hope of Gusto', '薰风的希望 神威', 'ガスタの希望 カムイ', 'Flip Effect Monster', 'Psychic', 'WIND', 2, 200, 1000, '反转：从自己卡组把1只名字带有「薰风」的调整特殊召唤。'),
(12829151, 'Kanan the Swordmistress', '女剑士 迦南', '女剣士カナン', 'Normal Monster', 'Warrior', 'EARTH', 4, 1400, 1400, '像蝴蝶飞舞像蜜蜂蜇人，双手持剑与盾的女战士。'),
(95789089, 'Kangaroo Champ', '袋鼠冠军', 'カンガルー・チャンプ', 'Effect Monster', 'Beast', 'EARTH', 4, 800, 700, '与这张卡进行战斗的怪兽，战斗伤害计算后变为守备表示。'),
(84103702, 'Kanikabuto', '甲壳蟹', 'カニカブト', 'Normal Monster', 'Aqua', 'WATER', 3, 650, 900, '螃蟹怪兽。用双手的大钳子切碎对方。'),
(6284176, 'Kanzashi the Rikka Queen', '六花圣簪', '六花聖カンザシ', 'XYZ Monster', 'Plant', 'WATER', 6, 2400, 2400, '6星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：怪兽被解放的场合，把这张卡1个超量素材取除，以自己或者对方的墓地1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽效果无效化，变成植物族。 ②：自己场上的植物族怪兽被效果破坏的场合，可以作为代替把自己的手卡·场上1只植物族怪兽解放。'),
(48109103, 'Kappa Avenger', '复仇的河童', '復讐のカッパ', 'Normal Monster', 'Aqua', 'WATER', 3, 1200, 900, '被同伴杀害，为了复仇而将心灵卖给邪恶的河童。'),
(85541675, 'Karakuri Anatomy', '机偶解体新书', 'カラクリ解体新書', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '每次名字带有「机巧」的怪兽的表示形式变更，给这张卡放置1个机巧指示物（最多2个）。此外，可以把场上存在的这张卡送去墓地，从自己卡组抽出这张卡放置的机巧指示物数量的卡。'),
(92300891, 'Karakuri Barrel mdl 96 "Shinkuro"', '机偶桶 真九六', 'カラクリ樽 真九六', 'Tuner Monster', 'Machine', 'EARTH', 2, 400, 400, '这张卡可以攻击的场合必须作出攻击。场上表侧攻击表示存在的这张卡被选择作为攻击对象时，这张卡的表示形式变成守备表示。这张卡1回合只有1次不会被战斗破坏。'),
(49296203, 'Karakuri Bonze mdl 9763 "Kunamzan"', '机偶法师 九七六叁', 'カラクリ法師 九七六参', 'Effect Monster', 'Machine', 'EARTH', 5, 2000, 1500, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡存在的场合，以自己场上1只「机巧」怪兽为对象才能发动。那只怪兽的表示形式变更，这张卡当作调整使用特殊召唤。这个效果的发动后，直到回合结束时自己不是机械族·地属性怪兽不能从额外卡组特殊召唤。 ②：这张卡可以攻击的场合必须作出攻击。 ③：这张卡被选择作为攻击对象的场合发动。这张卡的表示形式变更。'),
(39118197, 'Karakuri Bushi mdl 6318 "Muzanichiha"', '机巧武者 六三一八', 'カラクリ武者 六参壱八', 'Effect Monster', 'Machine', 'EARTH', 4, 1800, 600, '这张卡可以攻击的场合必须作出攻击。场上表侧攻击表示存在的这张卡被选择作为攻击对象时，这张卡的表示形式变成守备表示。场上存在的名字带有「机巧」的怪兽被破坏的场合，这张卡的攻击力上升400。');